    REACH_FACTOR = 1 + MITER_LIMIT;
    MIN_LOOP_AREA = 0.01;
    MERGE_SIN = 1e-12;
    byTag = (a, b) => a.kind - b.kind || a.owner - b.owner || a.loopIndex - b.loopIndex || a.edgeIndex - b.edgeIndex;
    edgeBBox = (e) => loopBBox([e]);
