                properties: {
                  min: { type: "number", description: "Lower bound (m\xB2)." },
                  max: { type: "number", description: 'Upper bound (m\xB2); omit for an open "at least" band.' },
                  source: {
                    type: "string",
                    description: "The brief phrase that licensed the band, quoted, so a failure can cite it."
                  }
                }
